struct eth_addr {
    uint8_t bytes[ETH_ADDR_LEN];
} __attribute__((__packed__));

struct eth_hdr {
    struct eth_addr d_addr;
    struct eth_addr s_addr;
    uint16_t type;
} __attribute__((__packed__));

typedef struct {
    union {
        struct in6_addr in6;
        struct {
            uint32_t pad[3];
            uint32_t ip;
        };
        uint8_t byte[16];
    };
} ipaddr_t;

struct vxlan {
    int vni;
    struct eth_addr inner_smac;
    struct eth_addr inner_dmac;
    struct ip_range vtep_local;
    struct ip_range vtep_remote;
};

struct vxlan_header {
    uint32_t flags:8;
    uint32_t reserved0:24;
    uint32_t vni:24;
    uint32_t reserved1:8;
};

struct vxlan_headers {
    struct eth_hdr eh;
    struct iphdr iph;
    struct udphdr uh;
    struct vxlan_header vxh;
} __attribute__((__packed__));

struct netif_port {
    int id; /* DPDK port id */
    int queue_num;
    int socket; /* cpu socket */
    bool enable;
    bool ipv6; /* local_ip, gateway_ip's address family */
    ipaddr_t local_ip;
    ipaddr_t gateway_ip;
    struct eth_addr gateway_mac;
    struct eth_addr local_mac;
    struct rte_mempool *mbuf_pool[THREAD_NUM_MAX];
    struct ip_range *local_ip_range;
    struct ip_range client_ip_range; /* only used by client; server use all client ip range */
    struct ip_range server_ip_range;

    union {
        void *kni;
        uint16_t virtio_user_id; /* can't be 0, 0 is nic itself*/
    };
    struct rte_ring *kni_mbuf_queue;
    struct vxlan *vxlan;

    /* bond */
    bool bond;
    uint8_t bond_mode;
    uint8_t bond_policy;
    uint8_t pci_num;
    char bond_name[BOND_NAME_MAX];

    union {
        char pci[PCI_LEN + 1];
        char pci_list[PCI_NUM_MAX][PCI_LEN + 1];
    };

    uint16_t port_id_list[PCI_NUM_MAX];
};

struct ip_range {
    ipaddr_t start;
    uint32_t list[256];
    uint32_t valid[256];
    uint8_t num;
};

#define IP_RANGE_NUM_MAX    32
struct ip_group {
    struct ip_range ip_range[IP_RANGE_NUM_MAX];
    int num;
};

struct ip_list {
    int num;
    int next;
    int af;
    ipaddr_t ip[IP_LIST_NUM_MAX];
};

struct net_stats {
    /* Increasing */

    /* interface */
    uint64_t pkt_rx;
    uint64_t pkt_tx;
    uint64_t byte_rx;
    uint64_t byte_tx;

    uint64_t tx_drop;
    uint64_t pkt_lost;
    uint64_t rx_bad;

    uint64_t tos_rx;

    /* socket */
    uint64_t socket_dup;
    uint64_t socket_open;
    uint64_t socket_close;
    uint64_t socket_error;

    /* tcp */
    uint64_t tcp_rx;
    uint64_t tcp_tx;

    uint64_t syn_rx;
    uint64_t syn_tx;

    uint64_t fin_rx;
    uint64_t fin_tx;

    uint64_t rst_rx;
    uint64_t rst_tx;

    uint64_t syn_rt;
    uint64_t fin_rt;
    uint64_t ack_rt;
    uint64_t push_rt;
    uint64_t ack_dup;

    uint64_t http_2xx;
    uint64_t tcp_req;
    uint64_t http_get;
    uint64_t http_post;
    uint64_t tcp_rsp;
    uint64_t http_error;

    uint64_t tcp_drop;

    /* udp */
    uint64_t udp_rx;
    uint64_t udp_tx;
    uint64_t udp_rt;
    uint64_t udp_drop;

    /* arp */
    uint64_t arp_rx;
    uint64_t arp_tx;

    /* icmp and icmp6 */
    uint64_t icmp_rx;
    uint64_t icmp_tx;

    /* kni */
    uint64_t kni_rx;
    uint64_t kni_tx;

    uint64_t other_rx;

    /* mutable  */
    uint64_t mutable_start[0];

    uint64_t rtt_tsc;
    uint64_t rtt_num;

    uint64_t cpusage;
    uint64_t socket_current;
};

struct tsc_time {
    uint64_t last;
    uint64_t count;
    uint64_t interval;
};

struct tick_time {
    uint64_t tsc;
    struct tsc_time tick;
    struct tsc_time ms100;
    struct tsc_time second;
};

struct socket_queue {
    struct socket_node head;
};

struct socket_timer {
    struct socket_queue queue;
};

struct tx_queue {
    uint16_t head;
    uint16_t tail;
    uint16_t tx_burst;
    struct rte_mbuf *tx[TX_QUEUE_SIZE];
};

/* launch every tick */
struct client_launch {
    uint64_t cc;
    uint64_t launch_next;
    uint64_t launch_interval;
    uint64_t launch_interval_default;
    uint64_t launch_reduce;
    uint32_t launch_num;
};

struct work_space {
    /* read mostly */
    uint8_t id;
    uint8_t ipv6:1;
    uint8_t server:1;
    uint8_t kni:1;
    uint8_t change_dip:1;
    uint8_t http:1;
    uint8_t flood:1;
    uint8_t fast_close:1;
    uint8_t disable_ack:1;
    uint8_t neigh_ignore:1;
    uint8_t mmap:1;

    /* bytes */
    uint32_t send_window;

    uint8_t tos;
    uint8_t port_id;
    uint8_t queue_id;

    uint16_t ip_id;
    bool lldp;
    bool exit;
    bool stop;
    bool start;
    uint16_t vlan_id;
    uint32_t vni:24;
    uint32_t vxlan:8;
    uint32_t vtep_ip; /* each queue has a vtep ip */
    uint32_t payload_size;
    struct tick_time time;
    struct cpuload load;
    struct client_launch client_launch;

    struct mbuf_cache tcp_opt;
    struct mbuf_cache tcp_data;
    union {
        struct mbuf_cache udp;
        struct mbuf_cache tcp;
    };

    FILE *log;
    struct config *cfg;
    struct netif_port *port;
    void (*run_loop)(struct work_space *ws);

    struct {
        int next;
        struct socket *sockets[TCP_ACK_DELAY_MAX];
    } ack_delay;
    struct tx_queue tx_queue;
    struct rte_mbuf *mbuf_rx[NB_RXD];
    struct ip_list  dip_list;
    struct socket_table socket_table;
};

struct socket_node {
    struct socket_node *next;
    struct socket_node *prev;
};

struct socket {
    /* ------16 bytes------  */
    struct socket_node node;    /* must be first */

    /* ------16 bytes------  */
    uint32_t rcv_nxt;
    uint32_t snd_nxt;
    uint32_t snd_una;

    uint8_t flags; /* tcp flags*/
    uint8_t state:4;
    uint8_t retrans:3;
    uint8_t keepalive:1;
    uint16_t log:1;
    uint16_t keepalive_request_num:15;

    /* ------16 bytes------  */
    uint64_t timer_tsc;
    uint16_t csum_tcp_data;
    uint16_t csum_ip;
    uint16_t csum_ip_opt;
    uint16_t csum_ip_data;

    /* ------16 bytes------  */
    uint32_t laddr;
    uint32_t faddr;
    uint16_t lport;
    uint16_t fport;
    union {
        uint16_t csum_tcp;
        uint16_t csum_udp;
    };
    uint16_t csum_tcp_opt;

#ifdef HTTP_PARSE
    /* ------16 bytes------  */
    /* http protocol         */
    int64_t http_length;
    uint8_t http_parse_state;
    uint8_t http_flags;
    uint8_t http_ack:1;
    uint8_t http_frags:7;
    uint8_t snd_window;
    uint32_t snd_max;
#endif
};

struct socket_port_table {
    struct socket sockets[0];
};

struct socket_pool {
    uint32_t num;
    uint32_t next;
    struct socket base[0] __attribute__((__aligned__(CACHE_ALIGN_SIZE)));
};

struct socket_table {
    uint32_t server_ip_num;
    uint32_t server_ip_min;
    uint32_t server_ip_max;

    uint16_t server_port_num;
    uint16_t server_port_min;
    uint16_t server_port_max;

    uint16_t client_port_num;
    uint16_t client_port_min;
    uint16_t client_port_max;

    uint32_t server_ip_port_num;

    uint8_t client_hop;
    uint8_t rss;
    uint8_t rss_id;
    uint8_t rss_num;
    struct socket_table *socket_table_hash[256]; /* server rss hash */
                     /* [client-ip][client-port][server-port][server-ip] */
    struct socket_port_table *ht[NETWORK_PORT_NUM];
    struct socket_pool socket_pool;
};

struct arphdr {
    uint16_t  ar_hrd;
    uint16_t  ar_pro;
    uint8_t   ar_hln;
    uint8_t   ar_pln;

    uint16_t  ar_op;

    struct eth_addr ar_sha;
    uint32_t  ar_sip;
    struct eth_addr ar_tha;
    uint32_t  ar_tip;
} __attribute__((__packed__));

struct mbuf_free_pool {
    int num;
    struct rte_mbuf *head;
};

struct mbuf_data {
    uint8_t data[MBUF_DATA_SIZE];
    bool ipv6;
    bool vxlan;
    uint16_t l2_len;
    uint16_t l3_len;
    uint16_t l4_len;
    uint16_t data_len;
    uint16_t total_len;
};

struct mbuf_cache {
    struct rte_mempool *mbuf_pool;
    struct mbuf_data data;
};

struct config {
    bool server;
    bool keepalive;
    bool ipv6;
    bool vxlan;
    bool kni;
    bool daemon;
    bool flood;
    bool jumbo;
    bool payload_random;
    bool client_hop;
    bool simd512;
    bool fast_close;
    bool clear_screen;
    bool disable_ack;
    uint8_t log_level;
    uint8_t flow;
    bool quiet;
    bool tcp_rst;
    bool neigh_ignore;
    bool flow_isolate;
    bool http;
    bool stats_http;    /* payload size >= HTTP_DATA_MIN_SIZE */
    uint8_t http_method;
    uint8_t tos;
    uint8_t pipeline;
    uint8_t tx_burst;
    uint8_t send_window;/* packets */
    uint8_t protocol;   /* TCP/UDP */
    uint16_t vlan_id;
    uint16_t jumbo_mtu;

    int ticks_per_sec;

    int lport_min;
    int lport_max;

    char kni_ifname[KNI_NAMESIZE];
    int af;

    uint32_t retransmit_timeout_sec;
    /* tsc */
    uint64_t retransmit_timeout;
    uint64_t keepalive_request_interval_us;
    /* tsc */
    uint64_t keepalive_request_interval;
    int keepalive_request_num;

    char http_host[HTTP_HOST_MAX];
    char http_path[HTTP_PATH_MAX];

    char payload_path[PAYLOAD_PATH_MAX];
    uint32_t payload_size[THREAD_NUM_MAX];
    int mss;

    int wait;
    int slow_start;
    uint32_t launch_num;
    int duration;
    int cps;        /* connection per seconds */
    int cc;         /* current connections */

    int cpu[THREAD_NUM_MAX];
    int cpu_num;

    /*
     * Running multiple instances on one host
     * dpdk rte_eal_init() --socket-meme
     * */
    char socket_mem[RTE_ARG_LEN];

    struct netif_port ports[NETIF_PORT_MAX];
    int port_num;

    struct vxlan vxlans[NETIF_PORT_MAX];
    int vxlan_num;

    int listen;
    int listen_num;

    struct ip_group client_ip_group;
    struct ip_group server_ip_group;
    struct ip_list  dip_list;
};

