// Prepare a valid, initialized MAC address in mac->bytes[0..5]
// Requirement: mac must be a valid non-null pointer with 6 bytes of data.
const uint8_t *rnd = *FUZZ_PARAM(uint8_t[6]);
for (int i = 0; i < 6; ++i) {
    mac->bytes[i] = rnd[i];
}
// Track that this eth_addr has been initialized with concrete bytes
FUZZ_SET_ATTR_INT(mac, "mac_init", 1);

// Provide a writable buffer large enough for common MAC string formats.
// We use an internal ephemeral buffer to satisfy the API requirement that 'str' be writable
// and large enough (at least 18 bytes for "aa:bb:cc:dd:ee:ff\0").
char outbuf[32];
for (size_t i = 0; i < sizeof(outbuf); ++i) { outbuf[i] = 0; }

// Call the target function
eth_addr_to_str((const struct eth_addr *)mac, outbuf);

// No return value to check; keep mac as an output for persistence.
// Validation: This stub ensures mac is initialized with 6 bytes and passes a sufficiently
// sized writable buffer to the function. The mac object is returned to the pool intact.

// mac must be writable and non-null; provided by the fuzzer runtime.
// Generate a candidate MAC address string. To improve coverage, sometimes use a well-formed
// colon-delimited string, otherwise pass through a random string.
const uint8_t *oct = *FUZZ_PARAM(uint8_t[6]);
char good_str[32];
int n = 0;
// Format a canonical hex MAC like aa:bb:cc:dd:ee:ff
n = snprintf(good_str, sizeof(good_str), "%02x:%02x:%02x:%02x:%02x:%02x",
             oct[0], oct[1], oct[2], oct[3], oct[4], oct[5]);
if (n <= 0 || n >= (int)sizeof(good_str)) { FUZZ_BAIL(); }

// Select between well-formed and fuzz string. Note: FUZZ_PARAM returns a deterministic
// value per build; selection still provides alternate pathing.
unsigned sel = *FUZZ_PARAM(unsigned);
std::string fuzz_s = FUZZ_PARAM_STR();
const char *mac_cstr = (sel & 1) ? good_str : fuzz_s.c_str();

// Invoke parser
int rc = eth_addr_init(mac, mac_cstr);

// Track initialization result for downstream stubs (0 commonly indicates success)
FUZZ_SET_ATTR_INT(mac, "mac_init", (rc == 0));
FUZZ_SET_ATTR_INT(mac, "eth_addr_init_rc", rc);

// Keep mac as an output so subsequent stubs can use it.
// Validation: The stub supplies a writable mac object and a NUL-terminated C string (either
// well-formed or fuzzed) and records the return code; mac persists for further use.

// Generate a candidate textual IP (may be IPv4 or IPv6). Ensure C-string form.
std::string s = FUZZ_PARAM_STR();
// ipaddr_init expects a null-terminated C string.
const char *cstr = s.c_str();

// Initialize the address from text; treat non-zero return as failure conservatively.
int ret = ipaddr_init(ip, cstr);
if (ret != 0) { FUZZ_BAIL(); }

// Mark as initialized and record the source string for potential debugging
FUZZ_SET_ATTR_INT(ip, "initialized", 1);
FUZZ_SET_ATTR_STR(ip, "source", cstr);

// Increment the address by a fuzzed 32-bit amount
uint32_t n = *FUZZ_PARAM(unsigned int);

// Capture a snapshot of the low 32-bits to validate n==0 behavior
uint32_t before_low = ip->ip;

// Call target
ipaddr_inc(ip, n);

// Property: if n == 0, the address must remain unchanged
if (n == 0) {
    FUZZ_ASSERT(ip->ip == before_low, "ipaddr_inc: low 32 bits changed when n == 0");
}

// Mark as initialized/updated for downstream consumers
FUZZ_SET_ATTR_INT(ip, "initialized", 1);

// Construct a valid prefix locally with 128 bits of fuzzed data.
ipaddr_t prefix_local;
const uint32_t (*w)[4] = FUZZ_PARAM(uint32_t[4]);
for (int i = 0; i < 4; ++i) {
    // Copy 4 x 32-bit words into the 16-byte address storage
    // Avoid alignment assumptions by using byte-wise copy
    const uint8_t *src = reinterpret_cast<const uint8_t*>(&(*w)[i]);
    for (int b = 0; b < 4; ++b) {
        prefix_local.byte[i * 4 + b] = src[b];
    }
}

// Generate the low 32-bit tail
uint32_t last = *FUZZ_PARAM(unsigned int);

// Capture expected high 96 bits (first 12 bytes)
uint8_t expected_high[12];
for (int i = 0; i < 12; ++i) { expected_high[i] = prefix_local.byte[i]; }

// Call target to compose addr from prefix_local (high 96 bits) and last (low 32 bits)
ipaddr_join(&prefix_local, last, addr);

// Property: low 32 bits of addr must equal 'last'
FUZZ_ASSERT(addr->ip == last, "ipaddr_join: low 32 bits not set to expected value");

// Property: high 96 bits of addr must equal prefix high 96 bits
bool high_ok = true;
for (int i = 0; i < 12; ++i) {
    if (addr->byte[i] != expected_high[i]) { high_ok = false; break; }
}
FUZZ_ASSERT(high_ok, "ipaddr_join: high 96 bits do not match prefix");

// Mark addr as initialized for downstream users
FUZZ_SET_ATTR_INT(addr, "initialized", 1);

// Note: checksum or upper-layer adjustments are intentionally not performed here; callers must handle them.
// Validation: The stub enforces both the low 32-bit assignment and high 96-bit preservation, ensuring proper API behavior.

// Randomize relevant bonding fields on the provided port to cover both true/false outcomes
unsigned int r0 = *FUZZ_PARAM(unsigned int);
unsigned int r1 = *FUZZ_PARAM(unsigned int);
unsigned int r2 = *FUZZ_PARAM(unsigned int);

// Choose whether bonding is enabled
port->bond = (r0 & 1) != 0;

// Choose a bonding mode in [0,7], and occasionally force 4 to hit the true branch
uint8_t mode = (uint8_t)(r1 % 8);
if ((r2 & 1) != 0) { mode = 4; }
port->bond_mode = mode;

// Call the target inline function
bool got = port_is_bond4(port);

// Property: result must equal (bond && bond_mode == 4)
bool expect = (port->bond && port->bond_mode == 4);
FUZZ_ASSERT(got == expect, "port_is_bond4() must reflect bond && bond_mode==4");

// Attach attributes for downstream stubs/diagnostics
FUZZ_SET_ATTR_INT(port, "bond", port->bond ? 1 : 0);
FUZZ_SET_ATTR_INT(port, "bond_mode", (int)port->bond_mode);
FUZZ_SET_ATTR_INT(port, "is_bond4", got ? 1 : 0);

// Validation summary:
// - Mutates only safe, documented fields (bond, bond_mode).
// - Asserts logical equivalence of implementation and spec for maximal path coverage.

// Preconditions: ip_range must be initialized and ip_range->num > 0
// Enforce required constraints to avoid division by zero inside ip_range_get
if (!ip_range) { FUZZ_BAIL(); }
if (ip_range->num == 0) { FUZZ_BAIL(); }

// Generate an 8-bit index value
uint8_t idx = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);

// Call target API
uint32_t got_ip = ip_range_get(ip_range, idx);

// Property: result equals list[idx % ip_range->num] (network order)
uint32_t expected_ip = ip_range->list[(uint8_t)(idx % ip_range->num)];
FUZZ_ASSERT(got_ip == expected_ip, "ip_range_get mismatch with list modulo");

// Preconditions: ip_range must be initialized and ip_range->num > 0
if (!ip_range || !addr) { FUZZ_BAIL(); }
if (ip_range->num == 0) { FUZZ_BAIL(); }

// Prepare an index in range [0,255]
uint8_t idx = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);

// Prepare the addr output buffer with the same IPv6 prefix as the range start.
// This is not strictly required by the API (function computes it), but ensures
// a deterministic, well-formed object for downstream consumers.
for (int i = 0; i < 12; ++i) { addr->byte[i] = ip_range->start.byte[i]; }

// Invoke target
ip_range_get2(ip_range, idx, addr);

// Validate that the first 12 bytes (prefix) match start as per description
for (int i = 0; i < 12; ++i) {
    if (addr->byte[i] != ip_range->start.byte[i]) { FUZZ_ASSERT(false, "ip_range_get2 prefix mismatch"); }
}

// addr is returned as an output object for reuse

// Preconditions: ip_range must be a valid pointer
if (!ip_range) { FUZZ_BAIL(); }

// Construct a start address with a random 96-bit prefix and a valid last byte in [1,254]
std::string prefix = FUZZ_PARAM_STR();
uint8_t start_last = (uint8_t)((*FUZZ_PARAM(unsigned int) % 254) + 1); // 1..254
ipaddr_t start = {};
for (int i = 0; i < 12; ++i) {
    start.byte[i] = (uint8_t)(i < (int)prefix.size() ? prefix[(size_t)i] : 0);
}
// Choose the last 4 bytes (IPv4 part). We'll randomize the first 3 bytes and set the last byte to start_last
for (int i = 12; i < 15; ++i) { start.byte[i] = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF); }
start.byte[15] = start_last;

// Pick num so that (last + num - 1) < 255; i.e., num in [1, 254 - last]
int num_cap = 254 - (int)start_last; // >= 0
int num = 0;
if (num_cap <= 0) { FUZZ_BAIL(); }
num = (int)(*FUZZ_PARAM(unsigned int) % (unsigned int)num_cap) + 1; // 1..num_cap

// start.ip must not be 0; ensure by forcing a nonzero IPv4 part
// If all last 4 bytes become zero (unlikely), force last byte to 1
bool all_zero = (start.byte[12] | start.byte[13] | start.byte[14] | start.byte[15]) == 0;
if (all_zero) { start.byte[15] = 1; }

int rc = ip_range_init(ip_range, start, num);
if (rc != 0) { FUZZ_BAIL(); }

// Mark initialized for downstream users
FUZZ_SET_ATTR_INT(ip_range, "initialized", 1);

// Preconditions: ip_range must be initialized and ip_range->num != 0 and < 255
if (!ip_range) { FUZZ_BAIL(); }
if (ip_range->num == 0) { FUZZ_BAIL(); }
if (ip_range->num >= 255) { FUZZ_BAIL(); }

// Build an address sharing the same 96-bit prefix
ipaddr_t addr = {};
for (int i = 0; i < 12; ++i) { addr.byte[i] = ip_range->start.byte[i]; }

// 50% chance to choose an existing member (to exercise duplicate path), otherwise a random candidate
bool choose_existing = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
if (choose_existing && ip_range->num > 0) {
    uint8_t idx = (uint8_t)((*FUZZ_PARAM(unsigned int)) % ip_range->num);
    // list entries are stored in network byte order; copy directly to the IPv4 tail
    uint32_t nip = ip_range->list[idx];
    addr.ip = nip; // sets the last 4 bytes
} else {
    // Create a candidate with last byte in [1,254]; other tail bytes random
    addr.byte[12] = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
    addr.byte[13] = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
    addr.byte[14] = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
    addr.byte[15] = (uint8_t)((*FUZZ_PARAM(unsigned int) % 254) + 1);
}

// Invoke target; -1 is an acceptable outcome for invalid/duplicate/capacity
(void)ip_range_add(ip_range, addr);

// Mark remains initialized for downstream use
FUZZ_SET_ATTR_INT(ip_range, "initialized", 1);

// Preconditions: ip_range must be initialized (valid populated list/valid[])
if (!ip_range) { FUZZ_BAIL(); }
if (ip_range->num == 0) { FUZZ_BAIL(); }

// Choose an IP to query: 50% existing, 50% non-existing (best-effort)
bool query_existing = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
uint32_t ip_net = 0;
if (query_existing) {
    uint8_t idx = (uint8_t)((*FUZZ_PARAM(unsigned int)) % ip_range->num);
    ip_net = ip_range->list[idx]; // network order
} else {
    // Build a candidate in the same /24-ish last 4 bytes space with last byte 1..254
    ipaddr_t tmp = {};
    for (int i = 0; i < 12; ++i) { tmp.byte[i] = ip_range->start.byte[i]; }
    tmp.byte[12] = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
    tmp.byte[13] = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
    tmp.byte[14] = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
    tmp.byte[15] = (uint8_t)((*FUZZ_PARAM(unsigned int) % 254) + 1);
    ip_net = tmp.ip; // network order
}

bool exists = ip_range_exist(ip_range, ip_net);

// Validate expectation when we intentionally chose an existing member
if (query_existing) {
    FUZZ_ASSERT(exists, "ip_range_exist should return true for stored member");
}

