import random
import string
from typing import List

# We generate a bytes buffer intended to be consumed by FUZZ_PARAM_STR() in the eth_addr_init stub.
# The stub sometimes chooses between our provided string and an internally formatted good string.
# We therefore focus on producing valid and interesting MAC address strings that exercise parser paths.
# Requirements for validity: six hex octets separated by delimiters, commonly ':'.
# We will generate a mix of canonical, uppercase, mixed delimiters, broadcast/multicast, and locally
# administered addresses. Keep length <= 4096.

HEX_LOWER = "0123456789abcdef"
HEX_UPPER = "0123456789ABCDEF"


def _octet(r: random.Random, width: int = 2, upper: bool = False) -> str:
    v = r.randrange(0, 256)
    fmt = f"{{:0{width}x}}" if not upper else f"{{:0{width}X}}"
    return fmt.format(v)


def _octet_value(r: random.Random, val: int, width: int = 2, upper: bool = False) -> str:
    fmt = f"{{:0{width}x}}" if not upper else f"{{:0{width}X}}"
    return fmt.format(val & 0xFF)


def _choose(r: random.Random, arr: List[str]) -> str:
    return arr[r.randrange(0, len(arr))]


def _canonical_mac(r: random.Random) -> str:
    # 6 octets, lowercase, ':' separated
    return ":".join(_octet(r) for _ in range(6))


def _uppercase_mac(r: random.Random) -> str:
    return ":".join(_octet(r, upper=True) for _ in range(6))


def _mixed_case_mac(r: random.Random) -> str:
    parts = []
    for _ in range(6):
        up = r.choice([True, False])
        parts.append(_octet(r, upper=up))
    return ":".join(parts)


def _dash_mac(r: random.Random) -> str:
    return "-".join(_octet(r) for _ in range(6))


def _dot_mac_cisco(r: random.Random) -> str:
    # Cisco dotted: xxxx.xxxx.xxxx
    parts = []
    for _ in range(3):
        # 2 bytes per chunk
        parts.append(_octet(r) + _octet(r))
    return ".".join(parts)


def _no_leading_zero_mac(r: random.Random) -> str:
    # still valid for many parsers: single hex digit for values < 16
    parts = []
    for _ in range(6):
        v = r.randrange(0, 256)
        if v < 16:
            parts.append(hex(v)[2:])
        else:
            parts.append(f"{v:02x}")
    return ":".join(parts)


def _broadcast_mac() -> str:
    return "ff:ff:ff:ff:ff:ff"


def _multicast_mac(r: random.Random) -> str:
    # Ensure multicast by setting LSB of first octet
    first = r.randrange(0, 256) | 0x01
    rest = [r.randrange(0, 256) for _ in range(5)]
    return ":".join(f"{b:02x}" for b in [first] + rest)


def _locally_administered_unicast_mac(r: random.Random) -> str:
    # Locally administered (bit1 set), unicast (bit0 cleared)
    first = (r.randrange(0, 256) | 0x02) & 0xFE
    rest = [r.randrange(0, 256) for _ in range(5)]
    return ":".join(f"{b:02x}" for b in [first] + rest)


def _oui_specific(oui: List[int], r: random.Random) -> str:
    # Supply known OUIs like 00:11:22 etc. Fill the last 3 bytes randomly
    tail = [r.randrange(0, 256) for _ in range(3)]
    arr = oui + tail
    return ":".join(f"{b:02x}" for b in arr)


def _padded_whitespace(r: random.Random, s: str) -> str:
    # Some parsers accept surrounding whitespace
    left = "" if not r.choice([True, False]) else _choose(r, [" ", "\t"]) * r.randrange(1, 3)
    right = "" if not r.choice([True, False]) else _choose(r, [" ", "\t"]) * r.randrange(1, 3)
    return f"{left}{s}{right}"


def _generate_one(r: random.Random) -> str:
    # Pool of patterns emphasizing valid formats
    gens = [
        _canonical_mac,
        _uppercase_mac,
        _mixed_case_mac,
        _dash_mac,
        _dot_mac_cisco,
        _no_leading_zero_mac,
        lambda rr: _padded_whitespace(rr, _canonical_mac(rr)),
        lambda rr: _padded_whitespace(rr, _uppercase_mac(rr)),
        lambda rr: _broadcast_mac(),
        _multicast_mac,
        _locally_administered_unicast_mac,
        lambda rr: _oui_specific([0x00, 0x11, 0x22], rr),
        lambda rr: _oui_specific([0xAC, 0xDE, 0x48], rr),  # DE:AD:BE:EF style but with AC:DE:48
    ]
    s = r.choice(gens)(r)

    # Occasionally vary delimiter to colon to align with strict parsers expecting ':'
    if r.random() < 0.15:
        # Normalize non-colon delimiters to ':'
        s = s.replace('-', ':').replace('.', ':')
        # If Cisco dotted, after replacement length may be odd; keep as-is since parser may reject.

    # Ensure length <= 64 for safety
    return s[:64]


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Select how many candidate strings to include; in this context FUZZ_PARAM_STR likely
    # consumes a single string, so we return one. Keep as bytes with NUL termination optional; the
    # fuzzer infrastructure typically appends NUL. We'll include a trailing newline occasionally.
    s = _generate_one(r)

    # Occasionally append a newline to exercise C-string read until NUL; newline should be ignored by strict parsers
    if r.random() < 0.2:
        s = s + "\n"

    # Bound total size
    if len(s) > 4096:
        s = s[:4096]

    return s.encode('ascii', errors='ignore')

import random
import ipaddress

def _rand_ipv4(rng: random.Random) -> str:
    # Avoid 0.0.0.0 and 255 in last octet; prefer unicast/routable-ish ranges, but include edge/private/mcast sometimes
    strategies = [
        "private", "public", "loopback", "linklocal", "multicast", "benchmark", "doc", "apipa"
    ]
    choice = rng.choice(strategies)
    if choice == "private":
        blocks = [ipaddress.IPv4Network("10.0.0.0/8"),
                  ipaddress.IPv4Network("172.16.0.0/12"),
                  ipaddress.IPv4Network("192.168.0.0/16")]
        net = rng.choice(blocks)
        addr = int(net.network_address) + rng.randrange(1, net.num_addresses - 2)
        return str(ipaddress.IPv4Address(addr))
    if choice == "public":
        # Use TEST-NET or random public-ish excluding specials
        while True:
            octets = [rng.randrange(1, 224), rng.randrange(0, 256), rng.randrange(0, 256), rng.randrange(1, 255)]
            a = octets[0]
            if a in (0, 10, 127, 169, 172, 192, 224):
                continue
            return ".".join(map(str, octets))
    if choice == "loopback":
        return f"127.{rng.randrange(0,256)}.{rng.randrange(0,256)}.{rng.randrange(1,255)}"
    if choice == "linklocal":
        return f"169.254.{rng.randrange(0,256)}.{rng.randrange(1,255)}"
    if choice == "multicast":
        return f"{rng.randrange(224,240)}.{rng.randrange(0,256)}.{rng.randrange(0,256)}.{rng.randrange(1,255)}"
    if choice == "benchmark":  # 198.18.0.0/15
        return str(ipaddress.IPv4Address(198 << 24 | 18 << 16 | rng.randrange(0, 2) << 16 | rng.randrange(0, 1) | rng.randrange(1, 255)))
    if choice == "doc":  # 192.0.2.0/24, 198.51.100.0/24, 203.0.113.0/24
        nets = [ipaddress.IPv4Network("192.0.2.0/24"), ipaddress.IPv4Network("198.51.100.0/24"), ipaddress.IPv4Network("203.0.113.0/24")]
        net = rng.choice(nets)
        addr = int(net.network_address) + rng.randrange(1, net.num_addresses - 1)
        return str(ipaddress.IPv4Address(addr))
    if choice == "apipa":  # 169.254.0.0/16
        return f"169.254.{rng.randrange(0,256)}.{rng.randrange(1,255)}"
    # Fallback
    return str(ipaddress.IPv4Address(rng.randrange(1, 0xFFFFFFFF)))


def _rand_ipv6(rng: random.Random) -> str:
    patterns = [
        "global", "linklocal", "unique_local", "ipv4_mapped", "6to4", "teredo", "loopback", "documentation"
    ]
    choice = rng.choice(patterns)
    if choice == "global":
        # 2000::/3
        hi = rng.randrange(0x2000, 0x6000)
        parts = [hi]
        parts += [rng.randrange(0, 0x10000) for _ in range(7)]
        addr = ":".join(f"{p:x}" for p in parts)
        return str(ipaddress.IPv6Address(addr))
    if choice == "linklocal":
        # fe80::/64 with randomized interface id
        parts = [0xfe80, 0, 0, 0, 0] + [rng.randrange(0, 0x10000) for _ in range(3)]
        addr = ":".join(f"{p:x}" for p in parts)
        return str(ipaddress.IPv6Address(addr))
    if choice == "unique_local":
        # fc00::/7
        prefix = rng.choice([0xfc00, 0xfd00])
        parts = [prefix] + [rng.randrange(0, 0x10000) for _ in range(7)]
        addr = ":".join(f"{p:x}" for p in parts)
        return str(ipaddress.IPv6Address(addr))
    if choice == "ipv4_mapped":
        # ::ffff:a.b.c.d
        v4 = _rand_ipv4(rng)
        return f"::ffff:{v4}"
    if choice == "6to4":
        # 2002:V4ADDR::/48
        v4 = ipaddress.IPv4Address(_rand_ipv4(rng))
        v4hex = f"{int(v4):08x}"
        return f"2002:{v4hex[0:4]}:{v4hex[4:8]}::{rng.randrange(0,1<<16):x}:{rng.randrange(0,1<<16):x}"
    if choice == "teredo":
        # 2001:0000::/32 with randomized parts
        parts = [0x2001, 0x0000] + [rng.randrange(0, 0x10000) for _ in range(6)]
        return ":".join(f"{p:x}" for p in parts)
    if choice == "loopback":
        return "::1"
    if choice == "documentation":
        # 2001:db8::/32
        parts = [0x2001, 0x0db8] + [rng.randrange(0, 0x10000) for _ in range(6)]
        addr = ":".join(f"{p:x}" for p in parts)
        return str(ipaddress.IPv6Address(addr))
    # Fallback random
    return str(ipaddress.IPv6Address(rng.getrandbits(128)))


def _maybe_shorthand(ip_str: str, rng: random.Random) -> str:
    # ipaddress will compress IPv6 automatically when converted to str; add variations
    if ":" in ip_str:
        # Mixed-case hex and leading zeros variations
        if rng.random() < 0.5:
            # Randomly upper-case some hextets
            parts = ip_str.split(":")
            new_parts = []
            for p in parts:
                if rng.random() < 0.5:
                    new_parts.append(p.upper())
                else:
                    new_parts.append(p)
            ip_str = ":".join(new_parts)
        if rng.random() < 0.3 and "::" not in ip_str:
            # Introduce a zero-run by expanding then compressing elsewhere via ipaddress (ensure validity)
            try:
                addr = ipaddress.IPv6Address(ip_str)
                # Expand to full, then choose a run to compress
                hextets = [f"{(int(addr) >> (16*(7-i)) ) & 0xFFFF:04x}" for i in range(8)]
                # find runs of zeros
                runs = []
                i = 0
                while i < 8:
                    if hextets[i] == "0000":
                        j = i
                        while j < 8 and hextets[j] == "0000":
                            j += 1
                        runs.append((i, j))
                        i = j
                    else:
                        i += 1
                if runs:
                    i, j = rng.choice(runs)
                    parts = []
                    for k in range(8):
                        if i <= k < j:
                            if k == i:
                                parts.append("")
                            continue
                        parts.append(str(int(hextets[k], 16)))
                    # Build with :: for the zero run
                    built = []
                    squeezed = False
                    for idx, p in enumerate(parts):
                        if p == "" and not squeezed:
                            built.append("")
                            squeezed = True
                        else:
                            built.append(p)
                    ip_str = ":".join(built)
                    if not ip_str.startswith("::") and not ip_str.endswith("::") and "::" not in ip_str:
                        # Ensure double colon present once
                        ip_str = ip_str.replace(":", "::", 1)
            except Exception:
                pass
    return ip_str


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Decide between IPv4 and IPv6 with a slight bias to IPv6 to exercise both branches
    if rng.random() < 0.55:
        s = _rand_ipv6(rng)
        s = _maybe_shorthand(s, rng)
    else:
        s = _rand_ipv4(rng)
    # Ensure it's a valid literal; if validation fails, regenerate deterministically by toggling family
    try:
        if ":" in s:
            ipaddress.IPv6Address(s)
        else:
            ipaddress.IPv4Address(s)
    except Exception:
        # Fallback to a simple, valid address
        s = "2001:db8::1" if rng.random() < 0.5 else "192.0.2.1"
    # Return as bytes including typical C-string style without extra NUL; caller provides c_str()
    return s.encode("ascii")
